def main():
 p=argparse.ArgumentParser();p.add_argument('--input',required=True);p.add_argument('--annotation',required=True);p.add_argument('--d8',required=True);p.add_argument('--output',required=True);a=p.parse_args();o=Path(a.output);o.mkdir(parents=True,exist_ok=True);im=cv2.imread(a.input); ann=json.loads(Path(a.annotation).read_text());d8=json.loads(Path(a.d8).read_text());cfg=load_config(Path(a.input).parents[2]/'configs/default.yaml');view=make_image_view(im,cfg.pipeline.roi,896);sx,sy=view.scale_x,view.scale_y;g=cv2.GaussianBlur(select_gray_channel(view.image,cfg.seam.color_channel),(5,5),0);rot,valid,_=__import__('scripts.experiment_real_seam_orientation',fromlist=['rotate_processing_image']).rotate_processing_image(g,0);prov=_track_inside_valid_region(find_boundary_track(rot),valid);model=d4._robust_model(prov);records=d4._scan_records(rot,valid,model);path=d4._path_for_records(records,model);selected={x.y:x for x in path.reliable_points};inter=set(path.interpolated_y);left=sorted([(float(x['x']),float(x['y'])) for x in ann['left_boundary_manual_points']],key=lambda z:z[1]);right=sorted([(float(x['x']),float(x['y'])) for x in ann['right_boundary_manual_points']],key=lambda z:z[1]);y0=max(left[0][1],right[0][1]);y1=min(left[-1][1],right[-1][1]); rows=[]
